package main

import "fmt"

type Nodo struct {
	Valor     int
	Siguiente *Nodo
}

func Invertir(cabeza *Nodo) *Nodo {
	var previo *Nodo
	actual := cabeza

	for actual != nil {
		siguiente := actual.Siguiente // guarda el resto de la lista
		actual.Siguiente = previo     // invierte el enlace
		previo = actual               // avanza previo
		actual = siguiente            // avanza actual
	}
	return previo // nueva cabeza
}

func imprimir(n *Nodo) {
	for ; n != nil; n = n.Siguiente {
		fmt.Print(n.Valor, " ")
	}
	fmt.Println()
}

func main() {
	lista := &Nodo{1, &Nodo{2, &Nodo{3, nil}}}
	imprimir(lista)          // 1 2 3
	lista = Invertir(lista)
	imprimir(lista)          // 3 2 1
}
```

**Cómo funciona:** recorres la lista con tres punteros (`previo`, `actual`, `siguiente`). En cada paso guardas el nodo siguiente, haces que el actual apunte al previo y avanzas. Al terminar, `previo` apunta al último nodo, que es la nueva cabeza.

